use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        forall|i: int|
            0 <= i < a.len() ==> result[i] == a[i],
        a@ == old(a@)
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            result.len() == i,
            i <= a.len(),
            forall|j: int| 0 <= j < i ==> result[j] == a[j],
            a@ == old(a@),
    {
        result.push(a[i]);
        i += 1;
    }

    result
}

} // verus!